-- 191_replace_decision_187_2020_customer_database_for_non_banking_financial_entities_ocr_corrupted_two_overlapping_rows_without_preamble_with_duplicated_articles_and_letterhead_footer.sql
--
-- إعادة رفع قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (187) لسنة 2020 بتاريخ 2020/12/9 بشأن إنشاء قاعدة بيانات لدى الشركات والجهات العاملة فى مجال الأنشطة المالية غير المصرفية بالخدمات التى تقدمها لعملائها:
-- ديباجة وثلاث مواد (صفحتان)، بلا فصول ولا قواعد مرفقة (فمفاتيح المواد كلها article_suffix_order = 0).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية OCR) =====
-- مخزَّن بالبذور صفّان متداخلان (article_no = 1 بـ1814 حرفاً و2 بـ806 أحرف، بلا عنوان وبلا hierarchical_location) من OCR رديء للصفحتين الممسوحتين، وبهما:
-- (1) لا ديباجة: غاب كل ما قبل "قرر" (القوانين التسعة المطلوب الاطلاع عليها: 54 لسنة 1975 و10 لسنة 1981 و95 لسنة 1992 و93 لسنة 2000 و148 لسنة 2001 و10 لسنة 2009 و141 لسنة 2014 و176 لسنة 2018 و18 لسنة 2020، وتاريخ جلسة المجلس 2020/12/9)، ولا عنوان القرار ولا رقمه ولا تاريخه؛
-- (2) الصف 1 يضم باقى القرار كله بعد بدء المادة الأولى (المادة الأولى والثانية والثالثة والتوقيع)، والصف 2 يكرر المادتين الثانية والثالثة من الصف 1 (فالمادتان مكررتان فى الصفين)؛
-- (3) المادة الأولى ناقصة البندين 1 و2 من قائمة محددات التقسيم ("نوع العميل" و"الفئة العمرية للعميل") فتبدأ القائمة بالبند 3، وبها النسبتان الجوهريتان مشوهتان بما لا يُقرأ: "(51%)" مخزَّنة "(9651)" و"(20%)" مخزَّنة "(9020)"، وكلمات مشوهة ("مصرفبة" و"ييانات" و"وفقأ" و"العملاعء" و"تقدمجا نهم ب در")؛
-- (4) عناوين المواد مشوهة ("المادة الشانية)" و"المادة الخالئة)")، وترويسة الصفحة الثانية وتذييلى الصفحتين (القرية الذكية والرقم البريدى والهاتف والفاكس وموقع الهيئة) مشوهة داخل المتن مرتين، وسطر التوقيع "رئيس مجلس إدارة الشيئة" بلا اسم الموقِّع؛ والمادة الثالثة مقطوعة (ناقص "نشره") فى الصف 1؛
-- (5) أرقام هندية متبقية، ونهايات أسطر CRLF، وتاريخ سريان هو تاريخ تشغيل البذر (2026-10-09) لا تاريخ القرار.
-- فلا يصلح النص المخزَّن للاستشهاد الرسمى ولا لإدخاله إلى سياق نموذج اللغة: نسبتا ملكية المرأة (51% و20%) مفقودتان، ومحددا التقسيم الأولان مفقودان، والمادتان 2 و3 تتكرران.
--
-- ===== المصدر والمنهجية =====
-- PDF من صفحتين (60 كيلوبايت) قدّمه صاحب المشروع باسم UG52513UG52514 (هو الاسم نفسه فى official_url المسجَّل فى laws)؛ هو صورتان ممسوحتان بالأبيض والأسود (JBIG2، 200 نقطة للبوصة) على ورق الهيئة، وبلا طبقة نص. قُرئ النص من الصورتين الأصليتين مباشرةً مقاطعَ مكبّرة (أرقام هذا القرار مطبوعة بالأرقام اللاتينية، فقُرئت أسطر الأرقام: رقم القرار 187 وتاريخه 2020/12/9، والقوانين التسعة، والنسبتين 51% و20%، من الصورة مباشرةً).
-- ثم قوبل النص المقروء بمخرجات OCR مستقل (tesseract ara) على الصفحتين: لم يظهر فرق فى لفظ غير ضجيج التعرف (التشوهات والترويسة والتذييل وبقايا الختم).
-- حُذفت ترويسة كل صفحة (شعار "الهيئة العامة للرقابة المالية FINANCIAL REGULATORY AUTHORITY" وسطر "رئيس الهيئة")، وتذييلها (القرية الذكية، والرقم البريدى، والهاتف والفاكس، وموقع الهيئة والبريد الإلكترونى بالعربية والإنجليزية Smart Village, Postal Code ... info@fra.gov.eg، ورقم الصفحة)، وسطر جهة الإصدار "مجلس إدارة الهيئة العامة للرقابة المالية" الذى يلى العنوان، وكلمة "قرر"، وختم "مكتب رئيس الهيئة" ورقمه المكتوب بخط اليد (46076) وتوقيع اليد (ليست من النص).
-- عنوان القرار ورقمه وتاريخه وموضوعه فى hierarchical_location للديباجة كما طُبعت (وكُتب فيها "العامة للرقابة المالية" بعد "الهيئة" بالصيغة الموحدة لعناوين الهجرات الأخرى؛ المطبوع "قرار مجلس إدارة الهيئة رقم (187) لسنة 2020 بتاريخ 2020/12/9"). الديباجة (article_no = 0 بعنوان "ديباجة القرار") من "بعد الاطلاع" إلى آخر "وبعد موافقة مجلس إدارة الهيئة"؛ وبعد "قرر" ثلاث مواد بعناوين وسطى "(المادة الأولى)" و"(المادة الثانية)" و"(المادة الثالثة)" فعناوين الصفوف "المادة الأولى" و"المادة الثانية" و"المادة الثالثة".
-- المادة 1: فقرة الالتزام بإنشاء قاعدة البيانات وتقسيم العملاء، فالبنود "1- ..." إلى "3- ..." (نوع العميل، الفئة العمرية، المنطقة الجغرافية) سطراً لكل بند، ثم فقرة الشخص الاعتبارى، فبندا الحالتين "1- ..." (51%) و"2- ..." (20%) سطراً لكل بند. والتوقيع باقٍ فى المادة 3 سطرين ("رئيس مجلس إدارة الهيئة / د. محمد عمران") كما طُبع.
-- لا تعديل على لفظ المطبوع. أُبقيت كتابته بلا تعديل: "بانشاء" فى المادة 1 بلا همزة، و"الالكتروني" فى المادة 3 بلا همزة، وجملة "تقسيم العملاء - بحد أدنى - وفقًا" بالشرطتين كما طُبعت (طُبعتا شرطتين طويلتين فكُتبتا "-")، و"(ذكر - أنثى)"، و"تملك" و"المنشأة"، والتكرار "الأنشطة المالية غير المصرفية" كما طُبع. وكُتب تنوين الفتح على الحرف السابق للألف ("وفقًا" و"نائبًا" و"موضحًا" و"يومًا" و"اعتبارًا") بالصيغة المعتمدة فى باقى الهجرات (المطبوع يضعه فوق الألف)، وأُسقطت الضمة فى "يُنشر" و"ويُعمل" ضمن إسقاط علامات التشكيل الصغيرة.
-- الأرقام لاتينية كما طُبعت، والنسب "%" كما طُبعت، وضُبطت المسافات حول الفاصلة والفاصلة المنقوطة والنقطتين (" ، " و" ؛" و" :").
--
-- ===== الهيكل =====
-- 4 صفوف، 4 نسخ (version_no = 1): ديباجة (article_no = 0) ثم المواد 1 و2 و3 بأرقامها الأصلية. أُبقى مفتاحا المادتين المخزَّنتين (1، 0) و(2، 0) فلا تعيد بذور 004/005/006 إدراج الصفوف القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2020-12-09 (تاريخ القرار المطبوع على الصفحة، معلن ومؤقت): المادة 3 تنص على العمل به "اعتباراً من اليوم التالى لتاريخ نشره بالوقائع المصرية"، وتاريخ النشر غير مطبوع على النسخة المقدمة، ولم يُعثر عليه فى مصدر ثانوى (تناولته الصحافة فى يناير 2021 دون ذكر العدد ولا تاريخ النشر)؛ فالتاريخ الفعلى للسريان لاحق لـ2020/12/9 ويجب أن يُراجَع على نسخة الوقائع المصرية. كان القديم تاريخ تشغيل البذر لا تاريخ سريان.
-- ولا تُعدَّل بيانات laws (التاريخ ورقم القرار والعنوان) فى هذه الهجرة.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (4 صفوف بديباجة سليمة والمادة 3 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، أو بقايا تلف، أو محتوى المواد، أو إجمالى الطول 2043 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix191$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 187 AND law_year = 2020 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[191] القرار 187/2020 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 4
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[191] القرار 187/2020 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[191] أُزيلت % مادة من القرار 187/2020 (نص مخزَّن صفّان متداخلان بلا ديباجة والمادتان 2 و3 مكررتان وترويسة وتذييل مشوهان ونسبتان وبندان مفقودة)', v_n;
  END IF;
END
$fix191$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 187 لسنة 2020 بتاريخ 2020/12/9 بشأن إنشاء قاعدة بيانات لدى الشركات والجهات العاملة في مجال الأنشطة المالية غير المصرفية بالخدمات التي تقدمها لعملائها$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون صناديق التأمين الخاصة الصادر بالقانون رقم (54) لسنة 1975 ؛
وعلى قانون الإشراف والرقابة على التأمين في مصر الصادر بالقانون رقم (10) لسنة 1981 ؛
وعلى قانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 ؛
وعلى قانون الإيداع والقيد المركزي للأوراق والأدوات المالية الصادر بالقانون رقم (93) لسنة 2000 ؛
وعلى قانون التمويل العقاري الصادر بالقانون رقم (148) لسنة 2001 ؛
وعلى القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى القانون رقم (141) لسنة 2014 بتنظيم مزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر ؛
وعلى قانون تنظيم نشاطي التأجير التمويلي والتخصيم الصادر بالقانون رقم (176) لسنة 2018 ؛
وعلى قانون تنظيم نشاط التمويل الاستهلاكي الصادر بالقانون رقم (18) لسنة 2020 ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2020/12/9 ؛$b0_0$
  FROM laws WHERE law_no = 187 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-12-09', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى$t1_0$, $b1_0$تلتزم الشركات والجهات العاملة في مجال الأنشطة المالية غير المصرفية الخاضعة لإشراف ورقابة الهيئة بانشاء قاعدة بيانات تتضمن الخدمات التي تقدمها لعملائها ، على أن يراعى في هذه القاعدة تقسيم العملاء - بحد أدنى - وفقًا للمحددات الآتية :
1- نوع العميل (ذكر - أنثى).
2- الفئة العمرية للعميل.
3- المنطقة الجغرافية لتقديم الخدمة.
وبالنسبة للشخص الاعتباري يدخل في شأن التقسيم الخاص بالمرأة على النحو المشار إليه بالفقرة السابقة ، الحالتين الآتيتين :
1- تملك امرأة واحدة على الأقل نسبة لا تقل عن (51%) من رأس مال الشركة أو المنشأة.
2- تملك امرأة واحدة على الأقل نسبة لا تقل عن (20%) من رأس مال الشركة أو المنشأة ، على أن تشغل امرأة واحدة على الأقل منصب رئيس مجلس الإدارة أو العضو المنتدب أو المدير التنفيذي أو نائبًا لأي منهم.$b1_0$
  FROM laws WHERE law_no = 187 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-12-09', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية$t2_0$, $b2_0$تلتزم الشركات والجهات العاملة في مجال الأنشطة المالية غير المصرفية الخاضعة لإشراف ورقابة الهيئة بتحديث قاعدة البيانات المشار إليها بالمادة الأولى من هذا القرار بشكل مستمر ، كما تلتزم بموافاة الهيئة بتقارير ربع سنوية عن تعاملاتها مع عملائها موضحًا بها التقسيم المشار إليه ، وذلك في موعد غايته خمسة عشر يومًا من تاريخ انتهاء الفترة المقدم عنها التقرير.$b2_0$
  FROM laws WHERE law_no = 187 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-12-09', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة$t3_0$, $b3_0$ينشر هذا القرار في الوقائع المصرية وعلى الموقع الالكتروني للهيئة ، ويعمل به اعتبارًا من اليوم التالي لتاريخ نشره بالوقائع المصرية.
رئيس مجلس إدارة الهيئة
د. محمد عمران$b3_0$
  FROM laws WHERE law_no = 187 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-12-09', 'active' FROM ins3_0;

DO $verify191$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 187 AND law_year = 2020 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[191] القرار 187/2020 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 4 THEN RAISE EXCEPTION '[191] عدد المواد % بدل 4', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2020-12-09';
  IF v_v <> 4 THEN RAISE EXCEPTION '[191] عدد النسخ % بدل 4', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%غيربة%' OR body LIKE '%مصرفبة%' OR body LIKE '%ييانات%' OR body LIKE '%وفقأ%' OR body LIKE '%العملاعء%' OR body LIKE '%الشيئة%' OR body LIKE '%الشانية%' OR body LIKE '%الخالئة%' OR body LIKE '%القرية الذكية%' OR body LIKE '%الرقم البريدى%' OR body LIKE '%تليفون%' OR body LIKE '%Smart Village%' OR body LIKE '%Postal Code%' OR body LIKE '%info@%' OR body LIKE '%fra.gov%' OR body LIKE '%WWW%' OR body LIKE '%نبنى الجسور%' OR body LIKE '%Building Bridges%' OR body LIKE '%(9651)%' OR body LIKE '%(9020)%' OR body LIKE '%١%' OR body LIKE '%٠%' OR body LIKE '%�%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%ال يقل%' OR body LIKE '%يوما من%' OR body LIKE '%الاتيتين%' OR body LIKE '%جا نهم%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[191] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على قانون صناديق التأمين الخاصة ا%' AND body LIKE '%ته المنعقدة بتاريخ 2020/12/9 ؛' AND body LIKE '%القانون رقم (54) لسنة 1975 ؛%' AND body LIKE '%القانون رقم (10) لسنة 1981 ؛%' AND body LIKE '%القانون رقم (95) لسنة 1992 ؛%' AND body LIKE '%القانون رقم (93) لسنة 2000 ؛%' AND body LIKE '%القانون رقم (148) لسنة 2001 ؛%' AND body LIKE '%القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق%' AND body LIKE '%القانون رقم (141) لسنة 2014 بتنظيم مزاولة نشاط تمويل%' AND body LIKE '%التأجير التمويلي والتخصيم الصادر بالقانون رقم (176) لسنة 2018 ؛%' AND body LIKE '%التمويل الاستهلاكي الصادر بالقانون رقم (18) لسنة 2020 ؛%' AND body LIKE '%المنعقدة بتاريخ 2020/12/9 ؛') THEN RAISE EXCEPTION '[191] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركات والجهات العاملة في مجال الأنشطة%' AND body LIKE '%ر التنفيذي أو نائبًا لأي منهم.' AND body LIKE '%بانشاء قاعدة بيانات تتضمن الخدمات التي تقدمها لعملائها ، على أن يراعى%' AND body LIKE '%تقسيم العملاء - بحد أدنى - وفقًا للمحددات الآتية :%' AND body LIKE '%1- نوع العميل (ذكر - أنثى).%' AND body LIKE '%2- الفئة العمرية للعميل.%' AND body LIKE '%3- المنطقة الجغرافية لتقديم الخدمة.%' AND body LIKE '%الحالتين الآتيتين :%' AND body LIKE '%1- تملك امرأة واحدة على الأقل نسبة لا تقل عن (51_) من رأس مال الشركة أو المنشأة.%' AND body LIKE '%2- تملك امرأة واحدة على الأقل نسبة لا تقل عن (20_) من رأس مال الشركة أو المنشأة ، على أن تشغل%' AND body LIKE '%أو نائبًا لأي منهم.') THEN RAISE EXCEPTION '[191] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركات والجهات العاملة في مجال الأنشطة%' AND body LIKE '%اء الفترة المقدم عنها التقرير.' AND body LIKE '%بتحديث قاعدة البيانات المشار إليها بالمادة الأولى من هذا القرار بشكل مستمر ،%' AND body LIKE '%بتقارير ربع سنوية%' AND body LIKE '%خمسة عشر يومًا من تاريخ انتهاء الفترة المقدم عنها التقرير.') THEN RAISE EXCEPTION '[191] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية وعلى الموق%' AND body LIKE '%د. محمد عمران' AND body LIKE '%ويعمل به اعتبارًا من اليوم التالي لتاريخ نشره بالوقائع المصرية.%' AND body LIKE '%رئيس مجلس إدارة الهيئة%' AND body LIKE '%د. محمد عمران') THEN RAISE EXCEPTION '[191] المادة 3 غير سليم'; END IF;
  IF v_len <> 2043 THEN RAISE EXCEPTION '[191] إجمالى طول المواد % بدل 2043', v_len; END IF;
  RAISE NOTICE '[191] القرار 187/2020: 4 مواد و4 نسخ، إجمالى % حرف', v_len;
END
$verify191$;

COMMIT;
